<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { menuConfig, isMenuGroup } from '../../config/menu'
import { createHttpChannel, createMqttChannel, deleteHttpChannel, deleteMqttChannel, editHttpChannel, editMqttChannel, fetchHttpChannel, fetchHttpChannels, fetchMqttChannel, fetchMqttChannels, type ChannelType, type HttpChannelListItem, type MqttChannelListItem } from '../../api/channel'
import ConfirmModal from '../modals/ConfirmModal.vue'
import HeaderTableEditor from '../../components/form/HeaderTableEditor.vue'

const router=useRouter(),route=useRoute()
const siblings=computed(()=>{for(const entry of menuConfig)if(isMenuGroup(entry)&&entry.children.some(c=>c.route===route.path))return entry.children;return[]})
const type=ref<ChannelType>('mqtt');const mqttRows=ref<MqttChannelListItem[]>([]);const httpRows=ref<HttpChannelListItem[]>([]);const loading=ref(false);const error=ref('');const page=ref(1);const pageSize=ref(10);const total=ref(0);const tableArea=ref<HTMLElement|null>(null)
const filters=reactive({broker_host:'',username:'',base_url:''});const pages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize.value)))
let observer:ResizeObserver|null=null;let resizeTimer:ReturnType<typeof setTimeout>|null=null
async function load(target=1){loading.value=true;error.value='';page.value=target;try{if(type.value==='mqtt'){const r=await fetchMqttChannels(target,pageSize.value,{broker_host:filters.broker_host.trim()||undefined,username:filters.username.trim()||undefined});mqttRows.value=r.data;total.value=r.total}else{const r=await fetchHttpChannels(target,pageSize.value,{base_url:filters.base_url.trim()||undefined});httpRows.value=r.data;total.value=r.total}}catch(e:any){error.value=e?.message||'加载通道失败';total.value=0}finally{loading.value=false}}
function changeType(value:ChannelType){type.value=value;page.value=1;error.value='';load(1)}
function clearFilters(){Object.assign(filters,{broker_host:'',username:'',base_url:''});load(1)}
function fmt(value:string){const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleString('zh-CN',{hour12:false})}
function adjustPageSize(){if(!tableArea.value)return;const next=Math.max(3,Math.min(50,Math.floor((tableArea.value.getBoundingClientRect().height-43)/49)));if(next!==pageSize.value){pageSize.value=next;load(1)}}
function scheduleResize(){if(resizeTimer)clearTimeout(resizeTimer);resizeTimer=setTimeout(adjustPageSize,120)}

const modal=ref(false),mode=ref<'create'|'edit'>('create'),saving=ref(false),detailLoading=ref(false),formError=ref(''),editId=ref('')
const mqttForm=reactive({broker_host:'',broker_port:1883,username:'',password:'',password_mode:'keep' as 'keep'|'replace'|'clear',password_configured:false,qos:1,connect_timeout:20,data_timeout:120,client_id:''})
const httpForm=reactive({base_url:'',default_timeout:20,default_headers:'{}'})
function resetForm(){Object.assign(mqttForm,{broker_host:'',broker_port:1883,username:'',password:'',password_mode:'keep',password_configured:false,qos:1,connect_timeout:20,data_timeout:120,client_id:''});Object.assign(httpForm,{base_url:'',default_timeout:20,default_headers:'{}'})}
function openCreate(){mode.value='create';editId.value='';formError.value='';resetForm();modal.value=true}
async function openEdit(row:MqttChannelListItem|HttpChannelListItem){mode.value='edit';formError.value='';resetForm();modal.value=true;detailLoading.value=true;try{if(type.value==='mqtt'){const id=(row as MqttChannelListItem).channel_mqtt_id;editId.value=id;const d=await fetchMqttChannel(id);Object.assign(mqttForm,{broker_host:d.broker_host,broker_port:d.broker_port,username:d.username||'',password_mode:'keep',password_configured:d.password_configured,qos:d.qos,connect_timeout:d.connect_timeout,data_timeout:d.data_timeout,client_id:d.client_id})}else{const id=(row as HttpChannelListItem).channel_http_id;editId.value=id;const d=await fetchHttpChannel(id);Object.assign(httpForm,{base_url:d.base_url,default_timeout:d.default_timeout,default_headers:JSON.stringify(d.default_headers||{},null,2)})}}catch(e:any){formError.value=e?.message||'加载详情失败'}finally{detailLoading.value=false}}
function parseHeaders(){let value:any;try{value=JSON.parse(httpForm.default_headers||'{}')}catch{throw new Error('公共请求头必须是有效的 JSON 对象')}if(!value||Array.isArray(value)||typeof value!=='object')throw new Error('公共请求头必须是 JSON 对象');for(const [k,v] of Object.entries(value))if(typeof k!=='string'||typeof v!=='string')throw new Error('公共请求头的键和值必须是字符串');return value as Record<string,string>}
async function save(){formError.value='';try{if(type.value==='mqtt'){if(!mqttForm.broker_host.trim())throw new Error('请输入 Broker 地址');if(mqttForm.broker_port<1||mqttForm.broker_port>65535)throw new Error('Broker 端口必须在 1～65535 之间');if(mqttForm.connect_timeout<=0||mqttForm.data_timeout<=0)throw new Error('超时时间必须大于 0');const payload:any={broker_host:mqttForm.broker_host.trim(),broker_port:Number(mqttForm.broker_port),username:mqttForm.username.trim()||null,qos:Number(mqttForm.qos),connect_timeout:Number(mqttForm.connect_timeout),data_timeout:Number(mqttForm.data_timeout)};if(mode.value==='create')payload.password=mqttForm.password||null;else if(mqttForm.password_mode==='replace'){if(!mqttForm.password)throw new Error('请输入新密码');payload.password=mqttForm.password}else if(mqttForm.password_mode==='clear')payload.password=null;saving.value=true;if(mode.value==='create')await createMqttChannel(payload);else await editMqttChannel(editId.value,payload)}else{if(!/^https?:\/\//i.test(httpForm.base_url.trim()))throw new Error('基础地址必须以 http:// 或 https:// 开头');if(httpForm.default_timeout<=0)throw new Error('默认超时时间必须大于 0');const payload={base_url:httpForm.base_url.trim(),default_headers:parseHeaders(),default_timeout:Number(httpForm.default_timeout)};saving.value=true;if(mode.value==='create')await createHttpChannel(payload);else await editHttpChannel(editId.value,payload)}modal.value=false;await load(page.value)}catch(e:any){formError.value=e?.message||'保存失败'}finally{saving.value=false}}

const deleteTarget=ref<MqttChannelListItem|HttpChannelListItem|null>(null),deleting=ref(false),deleteError=ref('')
const deleteName=computed(()=>!deleteTarget.value?'':type.value==='mqtt'?`${(deleteTarget.value as MqttChannelListItem).broker_host}:${(deleteTarget.value as MqttChannelListItem).broker_port}`:(deleteTarget.value as HttpChannelListItem).base_url)
async function confirmDelete(){if(!deleteTarget.value)return;deleting.value=true;deleteError.value='';try{if(type.value==='mqtt')await deleteMqttChannel((deleteTarget.value as MqttChannelListItem).channel_mqtt_id);else await deleteHttpChannel((deleteTarget.value as HttpChannelListItem).channel_http_id);deleteTarget.value=null;await load(page.value)}catch(e:any){deleteError.value=e?.message||'删除失败'}finally{deleting.value=false}}

onMounted(async()=>{await nextTick();adjustPageSize();if(!loading.value)await load(1);observer=new ResizeObserver(scheduleResize);if(tableArea.value)observer.observe(tableArea.value);window.addEventListener('resize',scheduleResize)})
onBeforeUnmount(()=>{observer?.disconnect();window.removeEventListener('resize',scheduleResize);if(resizeTimer)clearTimeout(resizeTimer)})
</script>

<template><main class="page-content"><section class="workspace"><nav v-if="siblings.length>1" class="sibling-tabs"><button v-for="item in siblings" :key="item.route" :class="{active:route.path===item.route}" @click="router.push(item.route)">{{item.name}}</button></nav><section class="card"><form class="toolbar channel-toolbar" @submit.prevent="load(1)"><div class="type-tabs"><button type="button" :class="{active:type==='mqtt'}" @click="changeType('mqtt')"><b>MQTT</b><small>消息通道</small></button><button type="button" :class="{active:type==='http'}" @click="changeType('http')"><b>HTTP</b><small>接口通道</small></button></div><template v-if="type==='mqtt'"><label>Broker 地址<input v-model="filters.broker_host" placeholder="主机名或 IP"></label><label>用户名<input v-model="filters.username" placeholder="模糊搜索用户名"></label></template><label v-else>HTTP 基础地址<input v-model="filters.base_url" class="url-search" placeholder="https://api.example.com"></label><div class="toolbar-actions"><button type="button" class="create inline-create" @click="openCreate">＋ 新增{{type==='mqtt'?' MQTT':' HTTP'}}通道</button><button type="button" @click="clearFilters">重置</button><button class="primary">查询</button></div></form><div v-if="error" class="alert">{{error}}<button @click="load(page)">重新加载</button></div><div ref="tableArea" class="table-area"><table v-if="type==='mqtt'"><thead><tr><th class="protocol-col">协议</th><th>Broker 地址</th><th>端口</th><th>创建时间</th><th class="operation">操作</th></tr></thead><tbody><tr v-for="row in mqttRows" :key="row.channel_mqtt_id"><td><span class="protocol mqtt">MQTT</span></td><td><strong>{{row.broker_host}}</strong></td><td>{{row.broker_port}}</td><td>{{fmt(row.created_at)}}</td><td class="actions"><button @click="openEdit(row)">编辑</button><button class="danger" @click="deleteTarget=row">删除</button></td></tr></tbody></table><table v-else><thead><tr><th class="protocol-col">协议</th><th>HTTP 基础地址</th><th>创建时间</th><th class="operation">操作</th></tr></thead><tbody><tr v-for="row in httpRows" :key="row.channel_http_id"><td><span class="protocol http">{{row.base_url.startsWith('https')?'HTTPS':'HTTP'}}</span></td><td><strong>{{row.base_url}}</strong></td><td>{{fmt(row.created_at)}}</td><td class="actions"><button @click="openEdit(row)">编辑</button><button class="danger" @click="deleteTarget=row">删除</button></td></tr></tbody></table><div v-if="loading" class="state">加载中...</div><div v-else-if="type==='mqtt'&&!mqttRows.length||type==='http'&&!httpRows.length" class="state">暂无{{type==='mqtt'?' MQTT':' HTTP'}}通道</div></div><footer v-if="total>0" class="pagination"><span class="pagination-info">共 {{total}} 条 · {{pages}} 页</span><div class="page-buttons"><button class="page-btn" :disabled="page<=1||loading" @click="load(1)" title="首页">«</button><button class="page-btn" :disabled="page<=1||loading" @click="load(page-1)" title="上一页">‹</button><button v-for="p in pages" :key="p" class="page-btn" :class="{active:p===page}" @click="load(p)">{{p}}</button><button class="page-btn" :disabled="page>=pages||loading" @click="load(page+1)" title="下一页">›</button><button class="page-btn" :disabled="page>=pages||loading" @click="load(pages)" title="末页">»</button></div></footer></section></section>

<div v-if="modal" class="overlay" @click.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><h2>{{mode==='create'?'新增':'编辑'}}{{type==='mqtt'?' MQTT':' HTTP'}}通道</h2><p>{{type==='mqtt'?'配置 Broker 连接和数据超时参数':'配置公共基础地址、请求头和超时时间'}}</p></div><button type="button" @click="modal=false">×</button></header><div class="modal-body"><div v-if="detailLoading" class="modal-loading">正在加载通道详情...</div><template v-if="type==='mqtt'"><label><div class="field-title">Broker 地址 <span>*</span></div><input v-model="mqttForm.broker_host" maxlength="30" placeholder="mqtt.example.com"></label><label><div class="field-title">Broker 端口 <span>*</span></div><input v-model.number="mqttForm.broker_port" type="number" min="1" max="65535"></label><label v-if="mode==='edit'" class="wide"><div class="field-title">客户端 ID <small>由系统生成，不可修改</small></div><input :value="mqttForm.client_id" disabled></label><label>用户名<input v-model="mqttForm.username" maxlength="20" placeholder="可选"></label><label v-if="mode==='create'">密码<input v-model="mqttForm.password" type="password" placeholder="可选"></label><div v-else class="wide password-field"><div class="field-title">密码配置 <small>当前状态：{{mqttForm.password_configured?'已配置':'未配置'}}</small></div><div class="password-box"><div><label><input v-model="mqttForm.password_mode" type="radio" value="keep">保留原密码</label><label><input v-model="mqttForm.password_mode" type="radio" value="replace">设置新密码</label><label><input v-model="mqttForm.password_mode" type="radio" value="clear">清除密码</label></div><input v-if="mqttForm.password_mode==='replace'" v-model="mqttForm.password" type="password" placeholder="请输入新密码"></div></div><label>QoS<select v-model.number="mqttForm.qos"><option :value="0">QoS 0</option><option :value="1">QoS 1</option><option :value="2">QoS 2</option></select></label><label>连接超时（秒）<input v-model.number="mqttForm.connect_timeout" type="number" min="1"></label><label>无数据超时（秒）<input v-model.number="mqttForm.data_timeout" type="number" min="1"></label></template><template v-else><label class="wide">HTTP 基础地址 <span>*</span><input v-model="httpForm.base_url" maxlength="200" placeholder="https://api.example.com"></label><label>默认超时（秒）<input v-model.number="httpForm.default_timeout" type="number" min="1"></label><HeaderTableEditor v-model="httpForm.default_headers" class="wide" title="公共请求头" hint="请求自身 Header 会覆盖同名值" /></template><div v-if="formError" class="form-error wide">{{formError}}</div></div><footer><button type="button" @click="modal=false">取消</button><button class="primary" :disabled="saving||detailLoading">{{saving?'保存中...':'保存'}}</button></footer></form></div>
<ConfirmModal :visible="!!deleteTarget" title="删除通道" :message="`确定删除「${deleteName}」吗？如果通道被请求或控制引用，服务端将拒绝删除。`" confirm-text="删除" :danger="true" :loading="deleting" :error="deleteError" @confirm="confirmDelete" @cancel="deleteTarget=null" /></main></template>

<style scoped>
