background:#3b82f6!important}.alert{display:flex;justify-content:space-between;margin:10px 20px 0;padding:9px 12px;border-radius:7px;color:#b91c1c;background:#fef2f2;font-size:12px}.alert button{border:0;color:#2563eb;background:none;cursor:pointer}.table-area{position:relative;flex:1;min-height:0;margin:12px 20px 0;overflow:hidden;border:1px solid #e2e8f0;border-radius:9px}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{height:48px;padding:0 14px;border-bottom:1px solid #edf1f6;text-align:left;font-size:12px}th{height:42px;color:#64748b;background:#f8fafc}.operation{width:150px}.protocol{display:inline-block;margin-right:9px;padding:3px 7px;border-radius:5px;font-size:9px}.protocol.mqtt{color:#6d28d9;background:#ede9fe}.protocol.http{color:#0369a1;background:#e0f2fe}.actions{display:flex;gap:6px}.actions button{padding:6px 10px;border:0;border-radius:6px;color:#2563eb;background:#eff6ff;cursor:pointer}.actions .danger{color:#dc2626;background:#fef2f2}.state{position:absolute;inset:43px 0 0;display:grid;place-items:center;color:#94a3b8;background:rgba(255,255,255,.85)}.pagination{height:56px;flex:none;display:flex;align-items:center;justify-content:space-between;padding:0 20px;color:#94a3b8;font-size:11px}.pagination div{display:flex;align-items:center;gap:10px}.pagination button{height:30px;padding:0 11px;border:1px solid #e2e8f0;border-radius:6px;color:#475569;background:#fff}.pagination button:disabled{opacity:.4}.overlay{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;background:rgba(15,23,42,.48)}.modal{width:680px;max-width:94vw;max-height:92vh;display:flex;flex-direction:column;border-radius:15px;background:#fff;overflow:hidden;box-shadow:0 24px 70px rgba(15,23,42,.25)}.modal>header{display:flex;justify-content:space-between;padding:19px 22px;border-bottom:1px solid #e2e8f0}.modal h2{margin:0 0 4px;font-size:19px}.modal header p{margin:0;color:#94a3b8;font-size:11px}.modal header>button{border:0;background:none;font-size:24px;cursor:pointer}.modal-body{position:relative;display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:20px 22px;overflow:auto}.modal-body label{display:flex;flex-direction:column;gap:6px;color:#475569;font-size:12px;font-weight:600}.modal-body label span{color:#dc2626}.modal-body input,.modal-body select,.modal-body textarea{width:100%;padding:9px 10px;border:1px solid #cbd5e1;border-radius:7px;color:#334155;background:#fff;outline:none}.modal-body input:disabled{color:#94a3b8;background:#f1f5f9}.modal-body textarea{resize:vertical;font:12px/1.6 ui-monospace,monospace}.modal-body small{color:#94a3b8;font-size:10px;font-weight:400}.wide{grid-column:1/-1}.password-box{display:flex;flex-direction:column;gap:8px;padding:12px;border:1px solid #e2e8f0;border-radius:9px}.password-box>div{display:flex;gap:18px}.password-box>div label{align-items:center;flex-direction:row;font-weight:400}.password-box input[type=radio]{width:auto}.modal-loading{position:absolute;inset:0;z-index:2;display:grid;place-items:center;background:rgba(255,255,255,.82);color:#64748b}.form-error{padding:9px 12px;border-radius:7px;color:#b91c1c;background:#fef2f2;font-size:11px}.modal>footer{display:flex;justify-content:flex-end;gap:8px;padding:14px 22px;border-top:1px solid #e2e8f0}.modal>footer button{height:36px;padding:0 17px;border:0;border-radius:7px;color:#475569;background:#f1f5f9;cursor:pointer}@media(max-width:750px){.page-content{padding:14px;overflow:auto}.workspace{height:auto;min-height:calc(100vh - 28px)}.toolbar{flex-wrap:wrap}.toolbar-actions{margin-left:0}.channel-head{align-items:flex-start;gap:10px;flex-direction:column}.type-tabs{width:100%}.type-tabs button{min-width:0;flex:1}.modal-body{grid-template-columns:1fr}.wide{grid-column:auto}}
.channel-head h2{margin:0 0 4px;color:#0f172a;font-size:18px}.channel-head p{margin:0;color:#94a3b8;font-size:11px}.channel-toolbar{align-items:center}.channel-toolbar .type-tabs{flex:none;margin-right:8px}.channel-toolbar .type-tabs button{min-width:112px;padding:7px 12px}.channel-toolbar .type-tabs small{font-size:9px}.pagination{border-top:1px solid #edf1f6}.pagination button{min-width:68px;background:#fff;transition:.15s}.pagination button:hover:not(:disabled){border-color:#93c5fd;color:#2563eb;background:#eff6ff}.actions button{min-width:52px;height:30px;padding:0 11px;border:1px solid #dbe3ee;background:#fff;transition:.15s}.actions button:hover{border-color:#93c5fd;color:#1d4ed8;background:#eff6ff}.actions .danger{border-color:#fecaca}.actions .danger:hover{border-color:#fca5a5;background:#fee2e2}.modal{width:720px;border:1px solid rgba(255,255,255,.7);border-radius:18px}.modal>header{position:relative;padding:22px 25px;background:linear-gradient(135deg,#f8fbff,#fff)}.modal>header:before{content:'';position:absolute;left:0;top:20px;bottom:20px;width:4px;border-radius:0 4px 4px 0;background:#3b82f6}.modal h2{font-size:20px;color:#0f172a}.modal header p{font-size:12px}.modal header>button{width:34px;height:34px;border-radius:9px;background:#f1f5f9;color:#64748b}.modal header>button:hover{background:#e2e8f0}.modal-body{gap:16px;padding:24px 25px;background:#f8fafc}.modal-body label{gap:8px;color:#334155;font-size:13px}.modal-body input,.modal-body select,.modal-body textarea{min-height:42px;padding:10px 12px;border-color:#d8e0eb;border-radius:9px;box-shadow:0 1px 2px rgba(15,23,42,.02)}.modal-body input:focus,.modal-body select:focus,.modal-body textarea:focus{border-color:#60a5fa;box-shadow:0 0 0 3px rgba(59,130,246,.12)}.modal-body textarea{resize:none}.modal-body small{line-height:1.5}.password-box{padding:16px;border-color:#dbeafe;background:#fff}.password-box>b{font-size:13px}.modal>footer{padding:16px 25px;background:#fff}.modal>footer button{min-width:88p