@media(max-width:900px){.channel-toolbar{align-items:stretch;flex-wrap:wrap}.channel-toolbar .type-tabs{width:100%}.channel-toolbar .type-tabs button{flex:1}}
.protocol-col{width:90px}.operation{text-align:center}.actions{height:48px;align-items:center;justify-content:center}.toolbar-actions .inline-create{color:#fff;background:#10b981}.toolbar-actions .inline-create:hover{color:#fff;background:#059669}.pagination{justify-content:flex-end;gap:4px;height:56px}.pagination-info{margin-right:12px;font-size:13px}.page-buttons{display:flex;gap:4px}.pagination .page-btn{min-width:34px;width:auto;height:34px;padding:0 8px;display:grid;place-items:center;border:1px solid #e2e8f0;border-radius:6px;background:#fff;color:#475569;font-size:13px}.pagination .page-btn:hover:not(:disabled){border-color:#94a3b8;background:#f1f5f9}.pagination .page-btn.active{border-color:#3b82f6;color:#fff;background:#3b82f6}.field-title{display:flex;align-items:center;gap:4px;color:#334155;font-size:13px;font-weight:600}.field-title span{color:#dc2626}.field-title small{margin-left:5px;color:#94a3b8;font-size:10px;font-weight:400}.password-field{display:flex;flex-direction:column;gap:8px}.password-field>.password-box{width:100%}
</style>
